/** Routes tagged `stock · lots`. */
export class StockLotsResource extends Resource {
  /**
   * O veículo da peça.
   *
   * Os dados do grupo `veicProd` da série: chassi, cor, motor, anos. Peça sem
   * veículo responde `registered = false`. A série de um depósito da empresa
   * irmã responde 404.
   *
   * `GET /v1/stock/serials/{id}/vehicle`
   *
   * @param id ID da série (Snowflake)
   * @param options Per-call overrides.
   */
  getSerialVehicle(id: string, options?: RequestOptions): Promise<S.StockSerialVehicleDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/serials/${seg(id)}/vehicle`, options });
  }

  /**
   * O que vence na janela pedida.
   *
   * ⚠️ `within_days = 0` significa **só os já vencidos**, e não "nenhum": é a
   * pergunta que a tela de perdas faz. O default do query string é 0 por isso.
   *
   * `GET /v1/stock/lots/expiring`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listExpiringLots(query?: StockLotsListExpiringLotsQuery, options?: RequestOptions): Promise<S.StockLotPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/lots/expiring`, query, options });
  }

  /**
   * Iterates every item of `listExpiringLots`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/lots/expiring`
   */
  listExpiringLotsAll(query?: StockLotsListExpiringLotsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockLotPageDto["items"]>[number], S.StockLotPageDto> {
    return new Paginator((page_token) => this.listExpiringLots({ ...query, page_token } as StockLotsListExpiringLotsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Os lotes **com o saldo de cada um**.
   *
   * Lista os lotes com **o saldo de cada um**, não apenas o cadastro.
   *
   * É o que sustenta rastreabilidade e validade: sem saldo por lote, não dá para
   * saber qual lote ainda existe no depósito nem qual vence primeiro.
   *
   * `GET /v1/stock/lots`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listLots(query?: StockLotsListLotsQuery, options?: RequestOptions): Promise<S.StockLotPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/lots`, query, options });
  }

  /**
   * Iterates every item of `listLots`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/lots`
   */
  listLotsAll(query?: StockLotsListLotsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockLotPageDto["items"]>[number], S.StockLotPageDto> {
    return new Paginator((page_token) => this.listLots({ ...query, page_token } as StockLotsListLotsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * As peças serializadas.
   *
   * Lista as peças serializadas e o estado de cada uma.
   *
   * Serializado é o caso em que a unidade é única e precisa ser seguida
   * individualmente, em vez de contada em quantidade.
   *
   * `GET /v1/stock/serials`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listSerials(query?: StockLotsListSerialsQuery, options?: RequestOptions): Promise<S.StockSerialPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/serials`, query, options });
  }

  /**
   * Iterates every item of `listSerials`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/serials`
   */
  listSerialsAll(query?: StockLotsListSerialsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockSerialPageDto["items"]>[number], S.StockSerialPageDto> {
    return new Paginator((page_token) => this.listSerials({ ...query, page_token } as StockLotsListSerialsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Grava o veículo da peça, conferindo
   * cada tag contra o leiaute da NF-e.
   *
   * `PUT /v1/stock/serials/{id}/vehicle`
   *
   * @param id ID da série (Snowflake)
   * @param body Request body.
   * @param options Per-call overrides.
   */
  putSerialVehicle(id: string, body: S.SerialVehicleBody, options?: RequestOptions): Promise<S.StockSerialVehicleDto> {
    return this._http.request({ method: 'PUT', path: `/v1/stock/serials/${seg(id)}/vehicle`, body, options });
  }

  /**
   * O formulário personalizado do lote.
   *
   * Grava os campos que o tenant declarou para lote ("temperatura de chegada",
   * "número do laudo"). A **definição** é cadastro e vive no catálogo; só o valor
   * preenchido é do estoque, porque o lote é do estoque.
   *
   * Substitui o conjunto inteiro: um campo que não vier no corpo é apagado.
   *
   * ⚠️ Campo obrigatório é exigido **aqui**, e nunca no movimento: o lote nasce
   * sozinho na conferência de entrada, e exigir cadastro ali faria uma decisão de
   * formulário parar a doca.
   *
   * `PUT /v1/stock/lots/{id}/custom-values`
   *
   * @param id ID do lote
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setLotCustomValues(id: string, body: S.SetLotCustomValuesBody, options?: RequestOptions): Promise<S.StockLotCustomValuesDto> {
    return this._http.request({ method: 'PUT', path: `/v1/stock/lots/${seg(id)}/custom-values`, body, options });
  }

  /**
   * O formulário personalizado da
   * peça serializada.
   *
   * Grava os campos que o tenant declarou para série ("quilometragem",
   * "horímetro", "cor"). Mesmo corpo e mesma resposta do formulário do lote: a
   * definição é do catálogo (escopo `serial`), o valor é do estoque.
   *
   * Substitui o conjunto inteiro: um campo que não vier no corpo é apagado. A
   * peça que já saiu do estoque continua editável: o campo descreve a peça, não
   * o movimento, e não alimenta documento fiscal.
   *
   * `PUT /v1/stock/serials/{id}/custom-values`
   *
   * @param id ID da peça serializada
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setSerialCustomValues(id: string, body: S.SetLotCustomValuesBody, options?: RequestOptions): Promise<S.StockLotCustomValuesDto> {
    return this._http.request({ method: 'PUT', path: `/v1/stock/serials/${seg(id)}/custom-values`, body, options });
  }

  /**
   * **para onde este lote foi**.
   *
   * É a resposta de um recall: o lote e todo movimento que o tocou, da entrada à
   * saída. Não é paginado de propósito - um rastro pela metade é pior que nenhum,
   * porque quem lê conclui que o resto não existe.
   *
   * `GET /v1/stock/lots/{id}/trace`
   *
   * @param id ID do lote
   * @param options Per-call overrides.
   */
  traceLot(id: string, options?: RequestOptions): Promise<S.StockLotTraceDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/lots/${seg(id)}/trace`, options });
  }
}

