/** Routes tagged `stock · movements`. */
export class StockMovementsResource extends Resource {
  /**
   * Com as alocações (procedência do CMV).
   *
   * Traz o movimento com as **alocações de custo**: de quais camadas cada pedaço da
   * saída saiu e por qual custo unitário.
   *
   * É a procedência do CMV. Sem essas linhas, o custo da venda é um número sem como
   * ser conferido depois.
   *
   * `GET /v1/stock/movements/{id}`
   *
   * @param id ID do movimento
   * @param options Per-call overrides.
   */
  getMovement(id: string, options?: RequestOptions): Promise<S.StockMovementDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/movements/${seg(id)}`, options });
  }

  /**
   * Saldo inicial de uma planilha.
   *
   * Colunas: `sku` e `quantidade` (obrigatórias), `deposito` (código, vazia = o
   * Principal), `custo_unitario`, `lote`, `validade`, `fabricacao` e `data`.
   * Cada linha vira uma entrada pelo mesmo `PostMovement` da tela, com chave
   * de idempotência por depósito, variante e lote. Com `dry_run`, só confere.
   * Modelo e regras em `docs/onboarding/importacao.md`.
   *
   * `POST /v1/stock/opening-balance/import`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  importOpeningBalance(body: S.SheetImportBody, options?: RequestOptions): Promise<S.SheetImportReportDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/opening-balance/import`, body, options });
  }

  /**
   * Histórico com keyset.
   *
   * Histórico de movimentos com paginação keyset por cursor opaco.
   *
   * É o extrato do estoque: cada linha é um fato que mexeu em saldo, com origem,
   * depósito, variante e quantidade.
   *
   * `GET /v1/stock/movements`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listMovements(query?: StockMovementsListMovementsQuery, options?: RequestOptions): Promise<S.StockMovementPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/movements`, query, options });
  }

  /**
   * Iterates every item of `listMovements`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/movements`
   */
  listMovementsAll(query?: StockMovementsListMovementsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockMovementPageDto["items"]>[number], S.StockMovementPageDto> {
    return new Paginator((page_token) => this.listMovements({ ...query, page_token } as StockMovementsListMovementsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Entrada abre camada, saída consome sob trava.
   *
   * Movimento é o único jeito de o saldo mudar. Entrada abre uma **camada de
   * custo** com quantidade e custo unitário próprios; saída consome camadas sob
   * trava de linha, na ordem que o método de custeio manda, e devolve as alocações
   * que formaram o custo daquela saída.
   *
   * Saldo é sempre a soma das camadas abertas, nunca uma coluna guardada: é o que
   * impede saldo e custo de divergirem. Saída sem disponível suficiente é recusada
   * com conflito, e a decisão acontece dentro da transação travada, porque decidir
   * fora dela passa em qualquer teste sequencial e fura na primeira concorrência
   * real.
   *
   * `POST /v1/stock/movements`
   *
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  postMovement(body: S.PostMovementBody, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.StockMovementDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/movements`, body, options });
  }

  /**
   * **E3**.
   *
   * Grava um movimento NOVO de sinal contrário apontando para o original. Nunca
   * `UPDATE`, nunca `DELETE`: corrigir o passado apaga a trilha, e estoque sem
   * trilha não fecha inventário nem se defende numa auditoria.
   *
   * ⚠️ Exige `stock.delete`, e não `stock.create`. Estornar é o mais perto de
   * apagar que o desenho permite, e a permissão de **desfazer** deve ser separada
   * da de lançar: o balconista lança, o supervisor estorna.
   *
   * `POST /v1/stock/movements/{id}/reverse`
   *
   * @param id ID do movimento a estornar
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  reverseMovement(id: string, body: S.ReverseBody, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.StockMovementDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/movements/${seg(id)}/reverse`, body, options });
  }
}

