/** Routes tagged `stock · receipts`. */
export class StockReceiptsResource extends Resource {
  /**
   * Encerra sem virar saldo.
   *
   * Encerra o recebimento sem virar saldo: o que estava conferido é descartado e
   * nada é movimentado.
   *
   * Existe porque um recebimento aberto por engano precisa sair da fila de
   * conferência sem deixar entrada fantasma no estoque.
   *
   * `POST /v1/stock/receipts/{id}/cancel`
   *
   * @param id ID do recebimento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  cancelReceipt(id: string, body: S.CancelBody, options?: RequestOptions): Promise<S.StockReceiptDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/receipts/${seg(id)}/cancel`, body, options });
  }

  /**
   * Declara a conferência encerrada.
   *
   * Não vira saldo: separa "terminei de conferir" de "aceito o que foi conferido"
   * para que a segunda decisão possa ser de outra pessoa.
   *
   * `POST /v1/stock/receipts/{id}/check`
   *
   * @param id ID do recebimento
   * @param options Per-call overrides.
   */
  checkReceipt(id: string, options?: RequestOptions): Promise<S.StockReceiptDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/receipts/${seg(id)}/check`, options });
  }

  /**
   * Abre o recebimento (**sem** virar saldo).
   *
   * Abrir recebimento **não mexe em saldo**. O ciclo é abrir, conferir e efetivar,
   * e só a efetivação vira estoque. É o oposto do que "a nota chegou, então o
   * estoque subiu" sugere, e é deliberado: a nota diz o que o fornecedor afirma ter
   * mandado; o que entrou é o que alguém contou na doca.
   *
   * Aceita XML de NF-e em base64, decodificado aqui na borda para que XML ilegível
   * seja atribuído a quem enviou e não pareça culpa do fornecedor. A mesma nota
   * recebida duas vezes no tenant responde conflito.
   *
   * `POST /v1/stock/receipts`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createReceipt(body: S.CreateReceiptBody, options?: RequestOptions): Promise<S.StockReceiptDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/receipts`, body, options });
  }

  /**
   * O recebimento com as linhas.
   *
   * Devolve o recebimento com as linhas, já interpretadas quando a origem foi uma
   * nota, e com o que a conferência registrou até agora.
   *
   * `GET /v1/stock/receipts/{id}`
   *
   * @param id ID do recebimento
   * @param options Per-call overrides.
   */
  getReceipt(id: string, options?: RequestOptions): Promise<S.StockReceiptDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/receipts/${seg(id)}`, options });
  }

  /**
   * Os documentos de custo
   * posterior do recebimento.
   *
   * Vêm do mais antigo ao mais novo, no máximo 50 por recebimento.
   *
   * `GET /v1/stock/receipts/{id}/cost-adjustments`
   *
   * @param id ID do recebimento
   * @param options Per-call overrides.
   */
  listCostAdjustments(id: string, options?: RequestOptions): Promise<S.StockCostAdjustmentListDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/receipts/${seg(id)}/cost-adjustments`, options });
  }

  /**
   * A fila de conferência.
   *
   * A fila de conferência: recebimentos abertos e o estado de cada um, paginados
   * por cursor opaco.
   *
   * `GET /v1/stock/receipts`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listReceipts(query?: StockReceiptsListReceiptsQuery, options?: RequestOptions): Promise<S.StockReceiptPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/receipts`, query, options });
  }

  /**
   * Iterates every item of `listReceipts`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/receipts`
   */
  listReceiptsAll(query?: StockReceiptsListReceiptsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockReceiptPageDto["items"]>[number], S.StockReceiptPageDto> {
    return new Paginator((page_token) => this.listReceipts({ ...query, page_token } as StockReceiptsListReceiptsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * **aqui a nota vira saldo** (E10).
   *
   * Devolve o recebimento e os movimentos gerados. `suggest_payable` SUGERE o
   * título a pagar no `pay` - não o cria: quem paga decide se
   * paga, e um título nascido sozinho vira pagamento que ninguém aprovou.
   *
   * `POST /v1/stock/receipts/{id}/post`
   *
   * @param id ID do recebimento
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  postReceipt(id: string, body: S.PostReceiptBody, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.StockReceiptPostDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/receipts/${seg(id)}/post`, body, options });
  }

  /**
   * O custo que chegou depois.
   *
   * CT-e do transportador, seguro ou abatimento que chega quando o recebimento
   * já foi efetivado. O que ainda está em estoque (onde quer que esteja, depois
   * de transferências) muda de custo; o que já saiu vai ao resultado como
   * variação de custo de aquisição, sem reescrever o CMV já apurado.
   *
   * O mesmo documento (recebimento, tipo e referência) lançado de novo devolve
   * o primeiro lançamento; com outro valor, é conflito.
   *
   * `POST /v1/stock/receipts/{id}/cost-adjustments`
   *
   * @param id ID do recebimento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  recordCostAdjustment(id: string, body: S.RecordCostAdjustmentBody, options?: RequestOptions): Promise<S.StockCostAdjustmentDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/receipts/${seg(id)}/cost-adjustments`, body, options });
  }

  /**
   * A despesa no **total da nota**.
   *
   * É o caminho de quem tem o frete no cabeçalho da NF-e e não por item. O total
   * fica no cabeçalho e o rateio o distribui na efetivação; o que as linhas já
   * declararam é respeitado, e só a diferença é rateada.
   *
   * `PUT /v1/stock/receipts/{id}/expenses`
   *
   * @param id ID do recebimento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setReceiptExpenses(id: string, body: S.SetReceiptExpensesBody, options?: RequestOptions): Promise<S.StockReceiptDto> {
    return this._http.request({ method: 'PUT', path: `/v1/stock/receipts/${seg(id)}/expenses`, body, options });
  }

  /**
   * Pede ao `pay` o título a pagar do documento posterior.
   *
   * O recebimento tem N títulos, um por documento: a mercadoria sai do próprio
   * recebimento, o frete ao transportador e o seguro à seguradora saem daqui.
   * Continua sendo sugestão, quem confirma e paga é o financeiro. Documento que
   * já tem título devolve o mesmo, sem chamar o `pay` de novo.
   *
   * `POST /v1/stock/receipts/{id}/cost-adjustments/{adjustment_id}/payable`
   *
   * @param id ID do recebimento
   * @param adjustmentId ID do documento de custo posterior
   * @param body Request body.
   * @param options Per-call overrides.
   */
  suggestCostAdjustmentPayable(id: string, adjustmentId: string, body: S.SuggestCostAdjustmentPayableBody, options?: RequestOptions): Promise<S.StockCostAdjustmentDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/receipts/${seg(id)}/cost-adjustments/${seg(adjustmentId)}/payable`, body, options });
  }

  /**
   * A conferência de uma linha.
   *
   * ⚠️ `received_quantity` está na **unidade do fornecedor** já registrada na
   * linha (a caixa da nota), e por isso não aceita `uom_id`: a linha já sabe qual
   * é a unidade, e deixar o cliente redeclará-la abriria a porta para conferir em
   * caixa uma linha que o fornecedor mandou em unidade.
   *
   * `PATCH /v1/stock/receipts/{id}/items/{item_id}`
   *
   * @param id ID do recebimento
   * @param itemId ID da linha
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateReceiptItem(id: string, itemId: string, body: S.UpdateReceiptItemBody, options?: RequestOptions): Promise<S.StockReceiptItemDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/stock/receipts/${seg(id)}/items/${seg(itemId)}`, body, options });
  }
}

