/** Routes tagged `stock · receiving`. */
export class StockReceivingResource extends Resource {
  /**
   * A adesão vigente da organização.
   *
   * Adesão à abertura automática de recebimento a partir das notas que a
   * distribuição DF-e trouxe. `is_enabled` falso quando nunca foi ligada.
   *
   * `GET /v1/stock/dfe-ingestion`
   *
   * @param options Per-call overrides.
   */
  getDfeIngestion(options?: RequestOptions): Promise<S.StockDfeIngestionConfigDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/dfe-ingestion`, options });
  }

  /**
   * As notas que ainda não viraram
   * recebimento, e por quê.
   *
   * Duas respostas possíveis em `reason`, e elas pedem ações diferentes:
   *
   * - `summary_only`: a nota chegou como **resumo**, que não carrega os itens
   *  por layout do Ambiente Nacional. Recebimento sem linha não é conferível;
   *  o caminho é manifestar (`POST /v1/fiscal/dfe/documents/{id}/manifest`) e
   *  baixar o documento completo (`.../download`), as duas no módulo fiscal.
   * - `not_ingested`: a nota está completa e a varredura ainda não a
   *  transformou em recebimento (adesão desligada, ou rodada ainda por vir).
   *
   * `GET /v1/stock/dfe-ingestion/pending`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listPendingInboundDocuments(query?: StockReceivingListPendingInboundDocumentsQuery, options?: RequestOptions): Promise<S.StockPendingInboundDocumentPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/dfe-ingestion/pending`, query, options });
  }

  /**
   * Iterates every item of `listPendingInboundDocuments`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/dfe-ingestion/pending`
   */
  listPendingInboundDocumentsAll(query?: StockReceivingListPendingInboundDocumentsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockPendingInboundDocumentPageDto["items"]>[number], S.StockPendingInboundDocumentPageDto> {
    return new Paginator((page_token) => this.listPendingInboundDocuments({ ...query, page_token } as StockReceivingListPendingInboundDocumentsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Liga ou desliga a entrada automática.
   *
   * ⚠️ Ligar exige o CNPJ interessado: a distribuição DF-e é por CNPJ, e sem ele
   * não há como saber de qual empresa do grupo é a nota. O depósito é opcional e
   * vazio significa o Principal da organização.
   *
   * `PUT /v1/stock/dfe-ingestion`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setDfeIngestion(body: S.SetDfeIngestionBody, options?: RequestOptions): Promise<S.StockDfeIngestionConfigDto> {
    return this._http.request({ method: 'PUT', path: `/v1/stock/dfe-ingestion`, body, options });
  }
}

