/** Routes tagged `stock · reservations`. */
export class StockReservationsResource extends Resource {
  /**
   * Devolve o disponível.
   *
   * Devolve o disponível imediatamente, sem mexer no saldo, porque a reserva nunca
   * tinha mexido.
   *
   * É o caminho para o carrinho abandonado e para o pedido cancelado antes do
   * faturamento.
   *
   * `DELETE /v1/stock/reservations/{id}`
   *
   * @param id ID da reserva
   * @param body Request body.
   * @param options Per-call overrides.
   */
  cancelReservation(id: string, body: S.CancelBody, options?: RequestOptions): Promise<S.StockReservationCancelDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/stock/reservations/${seg(id)}`, body, options });
  }

  /**
   * A reserva vira **baixa**.
   *
   * Devolve o **movimento**, não a reserva: o que interessa a quem confirmou é o
   * fato gravado, com o CMV apurado das camadas consumidas. Consumir a reserva e
   * gravar a saída acontecem na MESMA transação, e é isso que impede a promessa
   * de sobreviver à venda que ela existia para garantir.
   *
   * `POST /v1/stock/reservations/{id}/confirm`
   *
   * @param id ID da reserva
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  confirmReservation(id: string, body: S.ConfirmReservationBody, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.StockMovementDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/reservations/${seg(id)}/confirm`, body, options });
  }

  /**
   * Quem está prendendo a mercadoria.
   *
   * ⚠️ O `status` devolvido é o **gravado**. Reserva vencida só vira `expired`
   * quando a faxina passa, e o disponível já a ignora por leitura: a tela de
   * "reservas vivas" confere `expires_at` junto do estado, senão mostra como
   * presa mercadoria que já voltou a estar à venda.
   *
   * `GET /v1/stock/reservations`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listReservations(query?: StockReservationsListReservationsQuery, options?: RequestOptions): Promise<S.StockReservationPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/reservations`, query, options });
  }

  /**
   * Iterates every item of `listReservations`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/reservations`
   */
  listReservationsAll(query?: StockReservationsListReservationsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockReservationPageDto["items"]>[number], S.StockReservationPageDto> {
    return new Paginator((page_token) => this.listReservations({ ...query, page_token } as StockReservationsListReservationsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Segura o disponível por um prazo.
   *
   * Reserva prende o **disponível**, não o saldo: o item continua no depósito e
   * continua valendo dinheiro no balanço, mas não pode ser vendido duas vezes. Por
   * isso a reserva não gera movimento nenhum; quem gera é a confirmação.
   *
   * É idempotente pela origem: repetir com o mesmo par `(origin_type, origin_ref)`
   * devolve a mesma reserva em vez de criar outra. Sem disponível suficiente,
   * responde conflito. O prazo é obrigatório, para que reserva esquecida não prenda
   * estoque para sempre.
   *
   * `POST /v1/stock/reservations`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  reserve(body: S.ReserveBody, options?: RequestOptions): Promise<S.StockReservationDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/reservations`, body, options });
  }
}

