/** Routes tagged `stock · supplier returns`. */
export class StockSupplierReturnsResource extends Resource {
  /**
   * Vincula a NF-e emitida.
   *
   * ⚠️ Permissão **própria** (`stock.return.document`), pelo mesmo motivo da
   * remessa: quem devolve mercadoria não é necessariamente quem declara que a
   * nota fiscal daquela devolução existe.
   *
   * `POST /v1/stock/supplier-returns/{id}/document`
   *
   * @param id Id da devolução
   * @param body Request body.
   * @param options Per-call overrides.
   */
  attachSupplierReturnDocument(id: string, body: S.AttachRemittanceDocumentBody, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns/${seg(id)}/document`, body, options });
  }

  /**
   * Cancela um rascunho.
   *
   * Efetivada não volta atrás: a mercadoria saiu, e desfazer o documento não a
   * traz de volta.
   *
   * `POST /v1/stock/supplier-returns/{id}/cancel`
   *
   * @param id Id da devolução
   * @param body Request body.
   * @param options Per-call overrides.
   */
  cancelSupplierReturn(id: string, body: S.CancelSupplierReturnBody, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns/${seg(id)}/cancel`, body, options });
  }

  /**
   * Abre a devolução, em rascunho.
   *
   * Cada linha aponta uma linha do recebimento, e o serviço resolve a **camada
   * de custo** que ela criou. Nada sai do estoque aqui: a mercadoria só se move
   * na efetivação.
   *
   * `POST /v1/stock/supplier-returns`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createSupplierReturn(body: S.CreateSupplierReturnBody, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns`, body, options });
  }

  /**
   * O documento com as linhas.
   *
   * Cada linha aponta a linha do recebimento devolvida e a camada de custo de
   * origem: é ela, e não a fila do PEPS, que define por quanto a mercadoria sai.
   *
   * `GET /v1/stock/supplier-returns/{id}`
   *
   * @param id Id da devolução
   * @param options Per-call overrides.
   */
  getSupplierReturn(id: string, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/supplier-returns/${seg(id)}`, options });
  }

  /**
   * Pede a NF-e de
   * devolução ao módulo fiscal.
   *
   * O estoque manda o que só ele sabe (quais itens da nota de compra voltam e
   * quanto, na unidade do fornecedor); o fiscal compõe o resto da nota de compra
   * guardada: CFOP, tributos proporcionais, referência à chave de origem. Nota
   * autorizada fecha a obrigação sozinha (`fiscal_status = issued`).
   *
   * Só vale para recebimento que veio de uma NF-e importada: sem a nota de
   * compra não há o que referenciar, e a nota é emitida no módulo fiscal e
   * vinculada. Repetir o pedido com a tentativa aberta reenvia a mesma chave e
   * nunca gera outra nota.
   *
   * ⚠️ Permissão `stock.return.document`, a mesma de vincular: as duas fecham a
   * obrigação com uma nota que a SEFAZ autorizou, só muda quem a emite. Dispensar
   * continua com a sua (`stock.return.waive`), porque ali ninguém confere nada.
   *
   * `POST /v1/stock/supplier-returns/{id}/issue-document`
   *
   * @param id Id da devolução
   * @param body Request body.
   * @param options Per-call overrides.
   */
  issueSupplierReturnDocument(id: string, body: S.IssueSupplierReturnDocumentBody, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns/${seg(id)}/issue-document`, body, options });
  }

  /**
   * A fila do que ainda deve NF-e.
   *
   * Só devolução **efetivada** aparece: rascunho não deve nota, porque a
   * mercadoria ainda não saiu, e cobrar documento dele encheria a fila de
   * trabalho que ninguém pode fazer.
   *
   * `GET /v1/stock/supplier-returns/pending`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listPendingSupplierReturns(query?: StockSupplierReturnsListPendingSupplierReturnsQuery, options?: RequestOptions): Promise<S.StockSupplierReturnPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/supplier-returns/pending`, query, options });
  }

  /**
   * Iterates every item of `listPendingSupplierReturns`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/supplier-returns/pending`
   */
  listPendingSupplierReturnsAll(query?: StockSupplierReturnsListPendingSupplierReturnsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockSupplierReturnPageDto["items"]>[number], S.StockSupplierReturnPageDto> {
    return new Paginator((page_token) => this.listPendingSupplierReturns({ ...query, page_token } as StockSupplierReturnsListPendingSupplierReturnsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * As devoluções da organização.
   *
   * Rascunhos e efetivadas, com o recorte por recebimento e por estado. A
   * obrigação fiscal de cada documento vem no cabeçalho: quem precisa da fila de
   * notas pendentes usa `/v1/stock/supplier-returns/pending`.
   *
   * `GET /v1/stock/supplier-returns`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listSupplierReturns(query?: StockSupplierReturnsListSupplierReturnsQuery, options?: RequestOptions): Promise<S.StockSupplierReturnPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/stock/supplier-returns`, query, options });
  }

  /**
   * Iterates every item of `listSupplierReturns`, following `next_page_token` page after page.
   *
   * `GET /v1/stock/supplier-returns`
   */
  listSupplierReturnsAll(query?: StockSupplierReturnsListSupplierReturnsQuery, options?: RequestOptions): Paginator<NonNullable<S.StockSupplierReturnPageDto["items"]>[number], S.StockSupplierReturnPageDto> {
    return new Paginator((page_token) => this.listSupplierReturns({ ...query, page_token } as StockSupplierReturnsListSupplierReturnsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Efetiva: a mercadoria sai.
   *
   * ⚠️ Permissão **própria** (`stock.return.post`), separada de criar: montar o
   * rascunho não move nada, e efetivar tira mercadoria da prateleira por um
   * caminho que não volta atrás.
   *
   * `POST /v1/stock/supplier-returns/{id}/post`
   *
   * @param id Id da devolução
   * @param body Request body.
   * @param options Per-call overrides.
   */
  postSupplierReturn(id: string, body: S.PostSupplierReturnBody, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns/${seg(id)}/post`, body, options });
  }

  /**
   * Consulta de novo
   * a tentativa aberta.
   *
   * Nota em processamento ou fiscal que não respondeu deixam a tentativa em
   * `requested`; esta chamada pergunta ao fiscal outra vez e aplica o desfecho.
   * Sem tentativa aberta, devolve o documento como está.
   *
   * `POST /v1/stock/supplier-returns/{id}/refresh-document`
   *
   * @param id Id da devolução
   * @param options Per-call overrides.
   */
  refreshSupplierReturnDocument(id: string, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns/${seg(id)}/refresh-document`, options });
  }

  /**
   * Dispensa o documento.
   *
   * ⚠️ Permissão **própria** (`stock.return.waive`) e diferente da de vincular:
   * uma declara que a nota existe e é conferível contra a SEFAZ, a outra declara
   * que ela não é necessária, e ninguém confere.
   *
   * `POST /v1/stock/supplier-returns/{id}/waive`
   *
   * @param id Id da devolução
   * @param body Request body.
   * @param options Per-call overrides.
   */
  waiveSupplierReturnDocument(id: string, body: S.WaiveRemittanceBody, options?: RequestOptions): Promise<S.StockSupplierReturnDto> {
    return this._http.request({ method: 'POST', path: `/v1/stock/supplier-returns/${seg(id)}/waive`, body, options });
  }
}

